/* Birchline design tokens — Tailwind v4 @theme layer + Bright scheme override.
   Import after `@import "tailwindcss";` in your global stylesheet. */

@theme {
  /* ── Birchline Color Tokens ── */
  --color-ivory: #FAF9F5;
  --color-clay: #D97757;
  --color-clay-hover: #C7684C;
  --color-ink: #141413;
  --color-oat: #E3DACC;
  --color-green: #5F7348;
  --color-bronze: #916426;
  --color-red: #B04A4A;
  --color-red-hover: #9A3F3F;
  --color-plum: #7B6B8A;
  --color-teal: #5B8E8A;
  --color-blue: #526E92;
  --color-light-yellow: #F5E6B8;

  --color-white: #FFFFFF;
  --color-gray-100: #F0EEE6;
  --color-gray-300: #D1CFC5;
  --color-gray-500: #726F66;
  --color-gray-700: #3D3D3A;

  --color-success: var(--color-green);
  --color-warning: var(--color-bronze);
  --color-danger: var(--color-red);
  --color-danger-hover: var(--color-red-hover);
  --color-info: var(--color-blue);
  --color-highlight: var(--color-light-yellow);

  /* ── Semantic mappings (point to Birchline tokens) ── */
  --color-background: var(--color-ivory);
  --color-foreground: var(--color-ink);

  --color-card: var(--color-white);
  --color-card-foreground: var(--color-ink);
  --color-popover: var(--color-white);
  --color-popover-foreground: var(--color-ink);

  --color-primary: var(--color-clay);
  --color-primary-hover: var(--color-clay-hover);
  --color-primary-foreground: var(--color-white);

  --color-secondary: var(--color-gray-100);
  --color-secondary-foreground: var(--color-gray-700);

  --color-muted: var(--color-gray-100);
  --color-muted-foreground: var(--color-gray-500);

  --color-accent: var(--color-gray-100);
  --color-accent-foreground: var(--color-gray-700);

  --color-border: var(--color-gray-300);
  --color-input: var(--color-gray-300);
  --color-ring: var(--color-clay);

  /* ── Typography ── */
  --font-serif: ui-serif, Georgia, serif;
  --font-sans: system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, 'SF Mono', Menlo, monospace;

  /* ── Border Radius ── */
  --radius-xs: 4px;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;

  /* ── Shadows ── */
  --shadow-sm: 0 1px 2px rgba(20, 20, 19, 0.06);
  --shadow-md: 0 4px 10px rgba(20, 20, 19, 0.08);
  --shadow-lg: 0 12px 28px rgba(20, 20, 19, 0.12);

  /* ── Spacing (aliases) ── */
  --spacing-sp-1: 4px;
  --spacing-sp-2: 8px;
  --spacing-sp-3: 12px;
  --spacing-sp-4: 16px;
  --spacing-sp-5: 24px;
  --spacing-sp-6: 32px;
  --spacing-sp-7: 48px;
  --spacing-sp-8: 64px;
}

/* ── Alternative "Bright" scheme ──
   Overrides ONLY the accent hues; every other token (neutrals, surfaces,
   hovers) is intentionally omitted so it inherits the Muted base values. */
:root[data-theme="bright"] {
  --color-clay: #D05E38;
  --color-green: #658E3B;
  --color-bronze: #C2822A;
  --color-red: #C9413F;
  --color-blue: #608AD5;
  --color-plum: #9B67B6;
  --color-teal: #5DB2AC;
}

/* ── Dark mode ──
   Orthogonal to palette: data-mode="dark" remaps SURFACE + neutral roles
   (and dark-tuned status hues) to dark values. Brand accents (clay/ring) are
   left untouched, so they carry through from the active palette — the Muted
   palette keeps its clay, the Bright palette keeps its brighter clay.
   Placed AFTER the Bright block (equal specificity) so surface overrides win,
   letting Bright + Dark compose without a fourth explicit block. */
:root[data-mode="dark"] {
  --color-background: #1B1A17;
  --color-foreground: #ECE8DE;

  --color-card: #262420;
  --color-card-foreground: #ECE8DE;
  --color-popover: #262420;
  --color-popover-foreground: #ECE8DE;

  --color-secondary: #262420;
  --color-secondary-foreground: #C6C1B4;
  --color-muted: #211F1B;
  --color-muted-foreground: #9C978A;
  --color-accent: #302D27;
  --color-accent-foreground: #ECE8DE;

  --color-border: #37342C;
  --color-input: #37342C;

  /* status hues re-tuned to read on dark surfaces (light-mode values are too dark) */
  --color-success: #8FB06B;
  --color-warning: #D69C4E;
  --color-danger: #C9413F;
  --color-danger-hover: #B13937;
  --color-info: #7FA3D0;
  --color-highlight: #4A3C18;

  /* decorative raw neutrals used directly (guest avatar, placeholder icons) */
  --color-gray-300: #46433B;
  --color-gray-500: #8B8578;
}
